/*
 * A072011  Numbers k such that A072010(k) = k.
 * https://oeis.org/A072011
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n-th smallest element of the free monoid generated by 2
 *            and by p*(p+2) for twin primes p, p+2 with p == 1 (mod 4)
 *            (generator listing from the A071697 comment). Computed by
 *            enumerating all products <= a doubling bound X and sorting
 * Range:     u8 n <= 10, u16 n <= 68, u32 n <= 2718, u64 n <= 5000,
 *            u128 n <= 5000, big any n
 * Validated: standard, pass, 58 terms through n = 4634 (2026-11-07)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/mem.h"

static seq_t *A072011_cache = 0;
static size_t A072011_cnt = 0;
static seq_t A072011_X = 0;

static void A072011_walk(const seq_t *g, size_t ng, size_t i, seq_t v, seq_t X,
                         seq_t *out, size_t *cnt) {
    if (out) out[*cnt] = v;
    ++*cnt;
    for (size_t j = i; j < ng; ++j) {
        if (g[j] > X / v) break;
        A072011_walk(g, ng, j, v * g[j], X, out, cnt);
    }
}

static void A072011_sift(seq_t *a, size_t start, size_t end) {
    size_t root = start;
    while (2 * root + 1 < end) {
        size_t child = 2 * root + 1;
        if (child + 1 < end && a[child] < a[child + 1]) ++child;
        if (a[root] < a[child]) {
            seq_t t = a[root]; a[root] = a[child]; a[child] = t;
            root = child;
        } else return;
    }
}

static void A072011_sort(seq_t *a, size_t n) {
    if (n < 2) return;
    for (size_t s = n / 2; s-- > 0;) A072011_sift(a, s, n);
    for (size_t e = n - 1; e > 0; --e) {
        seq_t t = a[0]; a[0] = a[e]; a[e] = t;
        A072011_sift(a, 0, e);
    }
}

static bool A072011_build(seq_t X) {
    size_t L = 1;
    while ((seq_t)(L + 1) <= X / (seq_t)(L + 1)) ++L;
    size_t sz = L + 4;
    unsigned char *comp = (unsigned char *)calloc(sz, 1);
    if (!comp) return false;
    comp[0] = 1; comp[1] = 1;
    for (size_t i = 2; i * i < sz; ++i)
        if (!comp[i])
            for (size_t j = i * i; j < sz; j += i) comp[j] = 1;
    seq_t *g = mem_new(seq_t, sz);
    size_t ng = 0;
    if (X >= 2) g[ng++] = (seq_t)2;
    for (size_t p = 5; p <= L; p += 4) {
        if (comp[p] || comp[p + 2]) continue;
        if ((seq_t)p <= X / ((seq_t)p + 2)) {
            g[ng++] = (seq_t)p * ((seq_t)p + 2);
        }
    }
    free(comp);
    size_t cnt = 0;
    A072011_walk(g, ng, 0, (seq_t)1, X, 0, &cnt);
    seq_t *out = mem_new(seq_t, cnt);
    size_t c2 = 0;
    A072011_walk(g, ng, 0, (seq_t)1, X, out, &c2);
    mem_free(g);
    A072011_sort(out, c2);
    if (A072011_cache) mem_free(A072011_cache);
    A072011_cache = out;
    A072011_cnt = c2;
    A072011_X = X;
    return true;
}

seq_t a(idx_t n) {
    size_t need = (size_t)n;
    if (need == 0) return (seq_t)0;
    while (A072011_cnt < need) {
        seq_t X;
        if (A072011_X == 0) X = (seq_t)64;
        else {
            X = A072011_X * 2;
            if (X < A072011_X) return (seq_t)0;
        }
        if (!A072011_build(X)) return (seq_t)0;
    }
    return A072011_cache[need - 1];
}
